#ifndef PHIBROWSER_WIN_CLIENT_PHI_I18N_H_
#define PHIBROWSER_WIN_CLIENT_PHI_I18N_H_

#include <string>
#include <vector>

namespace phi_client {

// The client's localized strings — the Windows twin of the Mac's
// Localizable.xcstrings / NSLocalizedString.
//
// Catalog: resources/strings.json beside the exe, generated by
// tools/gen-strings-catalog.py from the MAC catalog (the product's single
// source of translations) plus this client's own Windows-only strings. Its
// shape is
//
//   {"locales":["en","de",…],
//    "strings":{"<key>":{"en":"New Tab","zh-Hans":"新建标签页", …}, …}}
//
// Keys follow the Mac convention `productArea.surface.purpose`, and a string
// whose English matches a Mac entry REUSES that entry's key so the two
// clients share one translation.
//
// Lookup NEVER fails: an untranslated key falls back to English, and an
// unknown key returns the key itself, which is loud enough to spot in a
// screenshot but cannot crash a menu build.
//
// Threading: everything runs on the browser UI thread, like the rest of the
// client. The catalog is read with plain Win32 file I/O, not base::ReadFile*,
// because the load is lazy and the UI thread disallows blocking calls once
// the message loop is running (the same trap phi_emoji.cc hit).

// The locale actually in use, e.g. "zh-Hans" (never empty).
const std::string& PhiActiveLocale();

// Locales the catalog carries, "en" first. Ordered for a picker.
const std::vector<std::string>& PhiAvailableLocales();

// The endonym for a locale tag ("Deutsch" for "de"), for the language picker.
// Falls back to the tag itself.
const wchar_t* PhiLocaleDisplayName(const std::string& tag);

// Applies the language preference. `tag` is a catalog locale, or EMPTY to
// follow the operating system's UI language (the default). Safe to call
// before the catalog has loaded. Returns true when the ACTIVE locale changed,
// which is the caller's cue to rebuild its chrome.
bool PhiSetLanguage(const std::string& tag);

// The stored preference as given to PhiSetLanguage — empty means "follow the
// system". Distinct from PhiActiveLocale(), which is always concrete.
const std::string& PhiLanguagePreference();

// The localized string for `key`. Valid for the lifetime of the process:
// switching languages never invalidates a pointer handed out earlier, so a
// menu built before the switch stays readable until it is rebuilt.
const wchar_t* PhiStr(const char* key);

// PhiStr with positional substitution: every "{0}", "{1}" … in the localized
// value is replaced by the matching argument. A placeholder with no argument
// is left as-is rather than dropped, so a mistranslated pattern degrades to
// something visible instead of silently losing data.
std::wstring PhiStrF(const char* key, const std::vector<std::wstring>& args);

}  // namespace phi_client

#endif  // PHIBROWSER_WIN_CLIENT_PHI_I18N_H_
